function sumBranchNumbers(root: TreeNode | null): number {
  const dfs = (node: TreeNode | null, soFar: number): number => {
    if (!node) return 0;
    const cur = soFar * 10 + node.val;
    if (!node.left && !node.right) return cur;
    return dfs(node.left, cur) + dfs(node.right, cur);
  };
  return dfs(root, 0);
}

