function sumBranchNumbers(root: TreeNode | null): number {
  if (!root) return 0;
  let total = 0;
  const stack: [TreeNode, number][] = [[root, 0]];
  while (stack.length) {
    const [node, soFar] = stack.pop()!;
    const cur = soFar * 10 + node.val;
    if (!node.left && !node.right) total += cur;
    if (node.left) stack.push([node.left, cur]);
    if (node.right) stack.push([node.right, cur]);
  }
  return total;
}

